    slug: 'mood-bipolar-spectrum-basics', id: '9efee7c8-09a1-518c-a873-a9a84f52fecd',
    title: 'Highs, lows, and in between',
    topic: 'Mood & depression',
    difficulty: 2,
    description: 'Bipolar disorder basics: what mania and hypomania are, how bipolar I and II differ, cyclothymia, and a landmark discovery.',
    tags: ['bipolar', 'mania', 'hypomania', 'cyclothymia'],
    questions: [
      {
        q: 'Bipolar disorder is defined by which pattern?',
        options: [
          'Episodes of elevated or irritable mood (mania or hypomania), usually alongside episodes of depression',
          'Rapid mood swings within a single hour',
          'Depression that only occurs in winter',
          'Constant anxiety mixed with low mood',
        ],
        answer: 0,
        why: 'The word "bipolar" points to two poles: the highs of mania or hypomania and the lows of depression. Episodes last days to weeks, not minutes.',
      },
      {
        q: 'What distinguishes mania from hypomania?',
        options: [
          'Hypomania includes depression, while mania does not',
          'Mania happens only at night',
          'Mania is more severe and longer, and can involve hospitalization or psychosis; hypomania is milder and shorter',
          'Hypomania is more dangerous than mania',
        ],
        answer: 2,
        why: '"Hypo" means "under." Hypomania is a noticeable lift in energy and mood without the severe impairment, psychosis, or need for hospital care that can come with full mania.',
      },
      {
        q: 'A diagnosis of bipolar I requires:',
        options: [
          'At least one depressive episode and no mania',
          'At least one manic episode',
          'Two hypomanic episodes in the same year',
          'Mood episodes that began in childhood',
        ],
        answer: 1,
        why: 'A single manic episode is enough for bipolar I. Depressive episodes are common and expected, but they are not required for the diagnosis.',
      },
      {
        q: 'Bipolar II involves:',
        options: [
          'Only manic episodes, without depression',
          'Milder depression than bipolar I',
          'Mania that lasts less than a week',
          'Hypomanic episodes plus major depressive episodes, without full mania',
        ],
        answer: 3,
        why: 'Bipolar II is not "bipolar lite." Its depressive episodes can be just as severe and often last longer; it is the highs that are milder.',
      },
      {
        q: 'Cyclothymia (cyclothymic disorder) is best described as:',
        options: [
          'A single lifelong episode of mild mania',
          'A seasonal form of bipolar disorder',
          'Bipolar disorder that begins after age 60',
          'Years of fluctuating hypomanic and depressive symptoms that never meet full episode criteria',
        ],
        answer: 3,
        why: 'Cyclothymia is a chronic, lower-amplitude version of the bipolar pattern. The ups and downs are real and persistent but stay below the threshold for full episodes.',
      },
      {
        q: 'Which is a classic sign of a manic episode?',
        options: [
          'A decreased need for sleep while still feeling energetic',
          'Sleeping far more than usual',
          'A total loss of appetite for days',
          'Severe fatigue after minor tasks',
        ],
        answer: 0,
        why: 'Sleeping three hours and feeling great is a hallmark. It is not insomnia, where a person wants sleep and cannot get it; the need itself seems to vanish.',
      },
      {
        q: 'Lithium, the first widely used mood stabilizer, was reported to calm mania by:',
        options: [
          'Sigmund Freud in Vienna',
          'Emil Kraepelin in Germany',
          'John Cade in Australia in 1949',
          'Aaron Beck in Philadelphia',
        ],
        answer: 2,
        why: 'Cade, a psychiatrist working in a small hospital, published his findings in 1949. Lithium, a simple element, remains one of the most effective treatments for bipolar disorder.',
      },
      {
        q: 'In bipolar disorder, "rapid cycling" means:',
        options: [
          'Mood changing several times an hour',
          'Four or more mood episodes in a year',
          'Two episodes over a lifetime',
          'Swinging between anxiety and calm within a day',
        ],
        answer: 1,
        why: 'Rapid cycling is defined by the number of distinct episodes in twelve months. It is a specifier, not a separate diagnosis, and can make treatment more complex.',
      },
      {
        q: 'Thoughts that race from topic to topic and speech that is fast and hard to interrupt are called:',
        options: [
          'Flight of ideas and pressured speech',
          'Word salad and echolalia',
          'Rumination and mutism',
          'Confabulation and perseveration',
        ],
        answer: 0,
        why: 'Both are classic features of mania. Word salad and echolalia are more associated with psychosis, while confabulation involves unintentionally invented memories.',
      },
      {
        q: 'Bipolar disorder was formerly known as:',
        options: [
          'Melancholic psychosis',
          'Circular neurosis',
          'Manic-depressive illness',
          'Hysterical mood disorder',
        ],
        answer: 2,
        why: '"Manic-depressive illness" was the standard term for much of the twentieth century. "Bipolar" became the official name in the 1980 US diagnostic manual.',
      },
    ],
