        options: ['A straight line rising upward', 'A perfectly flat line', 'A steady downward slope', 'An inverted U-shaped curve'],
        answer: 3,
        why: 'Performance rises with arousal up to a sweet spot, then falls off as pressure becomes too much. Too little pressure means boredom; too much means panic.',
