        q: 'Robert Sternberg\'s triangular theory of love names which three components?',
        options: [
          'Trust, respect, attraction',
          'Lust, attraction, attachment',
          'Friendship, romance, loyalty',
          'Intimacy, passion, commitment',
        ],
        answer: 3,
        why: 'Sternberg proposed that different kinds of love are combinations of intimacy (closeness), passion (desire and excitement) and commitment (the decision to stay).',
