    slug: 'trauma-window-of-tolerance', id: 'a9051494-69cc-5d84-9a3f-51b26d893153',
    title: 'Inside the window of tolerance',
    topic: 'Trauma & resilience',
    difficulty: 2,
    description: 'Dan Siegel\'s model of the zone where people can cope, what happens above and below it, and how the window can be widened.',
    tags: ['window of tolerance', 'siegel', 'regulation', 'nervous system'],
    questions: [
      {
        q: 'Which psychiatrist introduced the "window of tolerance" idea in his 1999 book "The Developing Mind"?',
        options: ['Bessel van der Kolk', 'Dan Siegel', 'Stephen Porges', 'Peter Levine'],
        answer: 1,
        why: 'Dan Siegel, a UCLA psychiatrist, used the phrase to describe the range of arousal in which a person can think, feel and function well.',
      },
      {
        q: 'The "window of tolerance" describes:',
        options: [
          'The range of nervous system arousal in which a person can cope and function',
          'The amount of time a person can tolerate a difficult conversation',
          'The number of stressful events a person can handle per year',
          'The period in childhood when the brain is most adaptable',
        ],
        answer: 0,
        why: 'Inside the window, emotions can rise and fall without overwhelming a person. Outside it, the body shifts into survival mode.',
      },
      {
        q: 'Which description best fits "hyperarousal," the state above the window?',
        options: [
          'Feeling numb and distant',
          'Feeling sleepy and slow',
          'Feeling calm but unfocused',
          'Feeling anxious, agitated, with racing thoughts',
        ],
        answer: 3,
        why: 'Hyperarousal is the "too much" zone. The body is revved up, alert to danger, and it is hard to settle or think clearly.',
      },
      {
        q: 'Which description best fits "hypoarousal," the state below the window?',
        options: [
          'Restless energy and irritability',
          'Rapid speech and difficulty sitting still',
          'Numbness, shutdown, and feeling foggy or disconnected',
          'Heightened senses and quick reactions',
        ],
        answer: 2,
        why: 'Hypoarousal is the "too little" zone. The system powers down, which can look like blankness, exhaustion or feeling far away from everything.',
      },
      {
        q: 'What effect does trauma tend to have on a person\'s window of tolerance?',
        options: [
          'It widens the window permanently',
          'It has no effect on the window',
          'It narrows the window, so smaller stressors push a person out of it',
          'It shifts the window upward only',
        ],
        answer: 2,
        why: 'After trauma, the nervous system can become quicker to sound the alarm. Everyday stress that others shrug off can tip a person into hyper- or hypoarousal.',
      },
      {
        q: 'How is the window of tolerance generally widened over time?',
        options: [
          'By avoiding all stress until the window resets',
          'Through gradual practice of regulation skills and safe, supportive relationships',
          'By pushing through intense distress as often as possible',
          'It cannot be widened once it has narrowed',
        ],
        answer: 1,
        why: 'The nervous system learns through repetition. Small, manageable experiences of feeling and settling, often with a trusted person, gradually expand what a person can handle.',
      },
      {
        q: 'Grounding exercises like naming five things you can see are designed to:',
        options: [
          'Bring attention back to the present moment through the senses',
          'Distract from feelings until they disappear',
          'Improve eyesight and memory',
          'Replace the need for professional support',
        ],
        answer: 0,
        why: 'Grounding uses the senses to signal to the brain that the present moment is safe, which can help pull a person back toward the window.',
      },
      {
        q: 'When a person is inside their window of tolerance, they can typically:',
        options: [
          'Feel no emotions at all',
          'Only think, not feel',
          'Only feel, not think',
          'Think and feel at the same time',
        ],
        answer: 3,
        why: 'The hallmark of the window is integration. Emotions are present but not in charge, so reasoning and feeling can work together.',
      },
      {
        q: 'Hypoarousal is most closely related to which survival response?',
        options: ['Fight', 'Flight', 'Fawn', 'Freeze'],
        answer: 3,
        why: 'Freeze and shutdown share the same downward direction. Where hyperarousal maps onto fight and flight, hypoarousal is the body going still and quiet.',
      },
      {
        q: 'What does "co-regulation" mean in this context?',
        options: [
          'Two people agreeing on rules for a conversation',
          'Settling one\'s nervous system through the calm presence of another person',
          'Taking turns describing stressful events',
          'Sharing the same medication schedule',
        ],
        answer: 1,
        why: 'Humans are built to calm down together. A steady voice, a familiar face or a slow breath beside us helps the nervous system find its way back into the window.',
      },
    ],
